shell_commands:
cat > /tmp/edit.py <<'EOF'
p='src/orchestration/tools/registry.test.ts'
s=open(p).read()
s=s.replace("""import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
""","""import {jest} from '@jest/globals';
import AjvModule from 'ajv';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
""")
s=s.rstrip()
assert s.endswith("});")
s=s[:-3]+"""
  it('validates a function-valued definition against the schema current at each call, compiling each schema object once', async () => {
    const compile = jest.spyOn(AjvModule.default.prototype, 'compile');
    const needsLocation = {type: 'object', required: ['location']};
    const needsCity = {type: 'object', required: ['city']};
    let current = needsLocation;
    const registry = new ToolRegistry();
    registry.register(
      () => ({name: 'get_weather', description: 'Weather lookup', inputSchema: current}),
      async () => 'ok'
    );

    const results: string[] = [];
    for (const schema of [needsLocation, needsCity, needsLocation, needsCity]) {
      current = schema;
      results.push((await registry.execute('get_weather', {location: 'Berlin'})).result);
    }
    const compileCalls = compile.mock.calls.length;
    compile.mockRestore();

    expect({results, compileCalls}).toEqual({
      results: ['ok', expect.stringMatching(/city/), 'ok', expect.stringMatching(/city/)],
      compileCalls: 2,
    });
  });
});
"""
open(p,'w').write(s)
EOF
python3 /tmp/edit.py && timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/tools/registry.test.ts 2>&1 | grep -v Experimental | tail -30
